#include "gb/base/embedded_data.h"

#include <cstdint>

#include "absl/types/span.h"
#include "gtest/gtest.h"

// These are generated by gb_embed_data in this directory's CMakeLists.txt.
#include "gb/base/embedded_data_test_bytes.h"
#include "gb/base/embedded_data_test_empty.h"
#include "gb/base/embedded_data_test_text.h"

namespace gb {
namespace {

bool IsAligned(const EmbeddedData& data) {
  return reinterpret_cast<uintptr_t>(data.GetBytes().data()) % 4 == 0;
}

TEST(EmbeddedDataTest, TextIsUnchanged) {
  const EmbeddedData& data = embedded_test::kText;
  EXPECT_EQ(data.GetText(),
            "Text with \"quotes\", a \\backslash, and UTF-8: \xc3\xa9");
  EXPECT_EQ(data.GetText().data()[data.GetText().size()], '\0');
  EXPECT_TRUE(IsAligned(data));
}

TEST(EmbeddedDataTest, EveryByteValueIsUnchanged) {
  absl::Span<const uint8_t> bytes = kTestBytes.GetBytes();
  ASSERT_EQ(bytes.size(), 256);
  for (int i = 0; i < 256; ++i) {
    EXPECT_EQ(bytes[i], i) << "at " << i;
  }
  EXPECT_EQ(bytes.data()[bytes.size()], 0);
  EXPECT_TRUE(IsAligned(kTestBytes));
}

TEST(EmbeddedDataTest, EmptyFile) {
  EXPECT_TRUE(kGbTestEmpty.GetBytes().empty());
  EXPECT_TRUE(kGbTestEmpty.GetText().empty());
  EXPECT_EQ(kGbTestEmpty.GetText().data()[0], '\0');
  EXPECT_TRUE(IsAligned(kGbTestEmpty));
}

}  // namespace
}  // namespace gb
